class Solution {
    public String[] findRestaurant(String[] list1, String[] list2) {
        java.util.HashMap<String, Integer> indexInList1 = new java.util.HashMap<>();
        for (int i = 0; i < list1.length; i++) {
            indexInList1.put(list1[i], i);
        }

        int bestSum = Integer.MAX_VALUE;
        java.util.List<String> answer = new java.util.ArrayList<>();
        for (int j = 0; j < list2.length; j++) {
            Integer i = indexInList1.get(list2[j]);
            if (i == null) {
                continue;
            }
            int sum = i + j;
            if (sum < bestSum) {
                bestSum = sum;
                answer.clear();
                answer.add(list2[j]);
            } else if (sum == bestSum) {
                answer.add(list2[j]);
            }
        }
        return answer.toArray(new String[0]);
    }
}

class Solution {
    public String[] findRestaurant(String[] list1, String[] list2) {
        java.util.List<String> answer = new java.util.ArrayList<>();
        int maxSum = list1.length + list2.length - 2;
        for (int sum = 0; sum <= maxSum; sum++) {
            int firstJ = Math.max(0, sum - (list1.length - 1));
            int lastJ = Math.min(list2.length - 1, sum);
            for (int j = firstJ; j <= lastJ; j++) {
                int i = sum - j;
                if (list1[i].equals(list2[j])) {
                    answer.add(list2[j]);
                }
            }
            if (!answer.isEmpty()) {
                return answer.toArray(new String[0]);
            }
        }
        return new String[0];
    }
}

